import{_ as a,o as l,c as r,a2 as e}from"./chunks/framework.CdvW4CUT.js";const p=JSON.parse('{"title":"檢舉回報","description":"向伺服方提出檢舉的相關說明。","frontmatter":{"title":"檢舉回報","description":"向伺服方提出檢舉的相關說明。"},"headers":[],"relativePath":"apply/report/index.md","filePath":"apply/report.md"}'),t={name:"apply/report/index.md"};function o(s,i,b,h,c,d){return l(),r("div",null,[...i[0]||(i[0]=[e('<h1 id="檢舉回報" tabindex="-1">檢舉回報 <a class="header-anchor" href="#檢舉回報" aria-label="Permalink to &quot;檢舉回報&quot;">​</a></h1><p>向伺服人員回報並尋求協助的管道<br> 當你今天家被破壞、東西被偷、生物被殺等<br> 只要是其他玩家影響你、造成你的權益受損都可以提出檢舉</p><h2 id="相關連結" tabindex="-1">相關連結 <a class="header-anchor" href="#相關連結" aria-label="Permalink to &quot;相關連結&quot;">​</a></h2><p><font size="4"><a href="/discord/">加入伺服Discord</a></font></p><ul><li>伺服器的Discord，要先加入才有辦法進行檢舉回報</li></ul><p><font size="4"><a href="/discord/customer_service/">客服系統</a></font></p><ul><li>須先<a href="/discord/">加入伺服Discord</a>，你不想透漏案件內容時會用到</li></ul><h2 id="受理項目" tabindex="-1">受理項目 <a class="header-anchor" href="#受理項目" aria-label="Permalink to &quot;受理項目&quot;">​</a></h2><ul><li>建築、設施被破壞</li><li>物品被偷</li><li>生物被殺</li><li>盜印畫作</li><li>被其他玩家影響遊玩 <ul><li><a href="/dungeon/intro/">副本服</a>僅受理外掛相關案件，其餘包含搶怪、殺人皆不受理</li></ul></li><li>有玩家做出違反<a href="/rule/">遊玩規範</a>的行為</li></ul><div class="tip custom-block"><p class="custom-block-title">詳細說明</p><p>關於受理項目的詳細說明<a href="/apply/report_detail/">請點我</a></p></div><h2 id="檢舉流程" tabindex="-1">檢舉流程 <a class="header-anchor" href="#檢舉流程" aria-label="Permalink to &quot;檢舉流程&quot;">​</a></h2><h3 id="需要準備的資訊" tabindex="-1">需要準備的資訊 <a class="header-anchor" href="#需要準備的資訊" aria-label="Permalink to &quot;需要準備的資訊&quot;">​</a></h3><p><b>被檢舉人的ID：</b>有時候你貼上的圖片會有好幾個ID在上面，讓我們知道你要檢舉誰<br><b>分流：</b>伺服有好幾個分流，讓我們知道要去哪個分流處理<br><b>事由：</b>你檢舉他的原因，像是破壞、偷竊、外掛等，必要時可以寫詳細點<br><b>圖片：</b><a href="/feature/core_protect/"><b>方塊紀錄查詢</b></a>的截圖，需完整截圖並涵蓋座標<br> 　　　當範圍很大時請多貼幾張圖片，<b>貴重物品一定要貼</b>(如烽火台、特殊物品等) <img src="https://i.imgur.com/KMGjUdN.png" style="height:90%;width:90%;"><br><b>代檢舉：</b>當你今天是<b>幫別人檢舉時</b>請務必註明，並註明是幫誰檢舉，且<b>你所附上的圖片必須是你自己的查詢紀錄</b><br><b>影片(非必要)：</b>檢舉外掛時，附上影片檔會讓伺服人員比較好判定<br><b>不須復原(非必要)：</b>處理檢舉時都會同時進行復原作業，如果不需要可以註明<br><b>備註(非必要)：</b>有需要伺服人員特別注意的地方可以寫出來，但請盡量簡短說明</p><h3 id="檢舉方式" tabindex="-1">檢舉方式 <a class="header-anchor" href="#檢舉方式" aria-label="Permalink to &quot;檢舉方式&quot;">​</a></h3><ol><li>打開<a href="/discord/">伺服Discord</a>找到<b>檢舉回報</b>頻道<br><img src="https://i.imgur.com/rx2mhvk.png" style="height:35%;width:35%;"></li><li>撰寫新貼文，以&quot;文字&quot;打上<b>被檢舉人的ID/分流/事由</b>等，並附上<b>相關證據圖片</b><b>(附上之圖片需為貼文者本人之查詢紀錄)</b><img src="https://i.imgur.com/faJv1zN.png" style="height:66%;width:66%;"></li><li>點開貼文編輯頁面裡的<b>查看較多資訊</b>，選擇案件<b>對應的分流標籤</b>後建立貼文 <img src="https://i.imgur.com/7cEZdxt.png" style="height:66%;width:66%;"><img src="https://i.imgur.com/rE07sIq.png" style="height:19%;width:19%;"></li><li>等待伺服人員處理(暫停/解除被檢舉人的遊玩契約、還原作業)<br> 處理完成後伺服人員會在你檢舉的那則貼文加上&quot;處理完成&quot;的標籤</li><li>檢查還原作業有沒有遺漏，有的話請<b>在貼文內說明</b>哪裡沒復原到(一樣要附上分流及座標等資訊)</li></ol><div class="warning custom-block"><p class="custom-block-title">私人檢舉</p><p>如果你不想讓別人知道你的案件內容(座標等資訊)<br> 請使用<a href="/discord/customer_service/"><b>客服系統</b></a>，並在客服頻道內以相同的流程進行檢舉</p></div><h2 id="注意事項" tabindex="-1">注意事項 <a class="header-anchor" href="#注意事項" aria-label="Permalink to &quot;注意事項&quot;">​</a></h2><ul><li>受理項目的說明無法涵蓋所有情況，案件是否受理由伺服人員認定之</li><li>檢舉資訊不完整時會要求補件，未補齊前伺服人員得不受理檢舉</li><li>代檢舉時請務必以文字註明是代檢舉的案件，並註明是幫誰檢舉 <ul><li>請謹慎提出檢舉，以避免造成當事人、被檢舉人及伺服人員的麻煩 <ul><li>必要時伺服人員會不受理案件或進行處置</li></ul></li></ul></li><li>請不要濫用檢舉功能，必要時伺服人員會進行處置 <ul><li>濫用檢舉係指無意義檢舉、報復性檢舉等狀況，由伺服人員認定之</li></ul></li></ul>',18)])])}const u=a(t,[["render",o]]);export{p as __pageData,u as default};
